// Generates the protocol constants for every side of the op boundary from protocol/ops.json.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const repo = join(root, '..', '..')
const p = JSON.parse(readFileSync(join(root, 'protocol/ops.json'), 'utf8'))
const banner =
  'Generated by spikes/native/scripts/gen-protocol.mjs from protocol/ops.json. Do not edit.'
const ops = Object.fromEntries(Object.entries(p.ops).map(([k, v]) => [k, v.code]))

const ts = `// ${banner}
export const PROTOCOL_VERSION = ${p.version}
export const Op = ${JSON.stringify(ops)} as const
export const NodeType = ${JSON.stringify(p.types)} as const
export const Prop = ${JSON.stringify(p.props)} as const
export const Event = ${JSON.stringify(p.events)} as const
export const LayoutKey = ${JSON.stringify(p.layoutKeys)} as const
export const Align = ${JSON.stringify(p.align)} as const
export const Space = ${JSON.stringify(p.space)} as const
export const TextRole = ${JSON.stringify(p.text)} as const
export const Controls = ${JSON.stringify(p.controls)} as const
export type NodeTypeName = keyof typeof NodeType
export type PropName = keyof typeof Prop
export type EventName = keyof typeof Event
export type SpaceToken = keyof typeof Space
export type TextRoleName = keyof typeof TextRole
`

const swiftEnum = (name, obj) =>
  `enum ${name}: UInt32 {\n${Object.entries(obj)
    .map(([k, v]) => `  case ${k} = ${v}`)
    .join('\n')}\n}\n`
const swift = `// ${banner}
let protocolVersion: UInt32 = ${p.version}
${swiftEnum('Op', Object.fromEntries(Object.entries(ops).map(([k, v]) => [k.toLowerCase().replace(/_(.)/g, (_, c) => c.toUpperCase()), v])))}
${swiftEnum('NodeType', p.types)}
${swiftEnum('Prop', p.props)}
${swiftEnum('EventKind', p.events)}
${swiftEnum('LayoutKey', p.layoutKeys)}
let spaceTokens: [String: Float] = [${Object.entries(p.space)
  .map(([k, v]) => `"${k}": ${v}`)
  .join(', ')}]
let alignTokens: [String: Float] = [${Object.entries(p.align)
  .map(([k, v]) => `"${k}": ${v}`)
  .join(', ')}]
let textRoles: [String: (size: Double, weight: Double)] = [${Object.entries(p.text)
  .map(([k, v]) => `"${k}": (${v.size}, ${v.weight})`)
  .join(', ')}]
let controlMinHeight: Float = ${p.controls.minHeight.ios}
let buttonPadX: Float = ${p.controls.buttonPadX}
`

const rust = `// ${banner}
pub mod key {
${Object.entries(p.layoutKeys)
  .map(
    ([k, v]) => `    pub const ${k.replace(/[A-Z]/g, (c) => '_' + c).toUpperCase()}: u32 = ${v};`,
  )
  .join('\n')}
}
pub mod align {
${Object.entries(p.align)
  .map(([k, v]) => `    pub const ${k.toUpperCase()}: u32 = ${v};`)
  .join('\n')}
}
`

const snake = (k) =>
  /^[A-Z_]+$/.test(k) ? k : k.replace(/(?<=[a-z])[A-Z]/g, (c) => '_' + c).toUpperCase()
const ktObj = (name, obj) =>
  `object ${name} {\n${Object.entries(obj)
    .map(([k, v]) => `    const val ${snake(k)} = ${v}`)
    .join('\n')}\n}\n`
const kotlin = `// ${banner}
package dev.weft.spike

const val PROTOCOL_VERSION = ${p.version}
${ktObj('Op', ops)}
${ktObj('NodeType', p.types)}
${ktObj('Prop', p.props)}
${ktObj('EventKind', p.events)}
${ktObj('LayoutKey', p.layoutKeys)}
val propNames = mapOf(${Object.entries(p.props)
  .map(([k, v]) => `${v} to "${k}"`)
  .join(', ')})
val spaceTokens = mapOf(${Object.entries(p.space)
  .map(([k, v]) => `"${k}" to ${v}f`)
  .join(', ')})
val alignTokens = mapOf(${Object.entries(p.align)
  .map(([k, v]) => `"${k}" to ${v}f`)
  .join(', ')})
data class TextRoleSpec(val size: Float, val weight: Int)
val textRoles = mapOf(${Object.entries(p.text)
  .map(([k, v]) => `"${k}" to TextRoleSpec(${v.size}f, ${v.weight})`)
  .join(', ')})
const val CONTROL_MIN_HEIGHT = ${p.controls.minHeight.android}f
const val BUTTON_PAD_X = ${p.controls.buttonPadX}f
`

writeFileSync(join(root, 'android/app/src/main/kotlin/dev/weft/spike/Protocol.gen.kt'), kotlin)
writeFileSync(join(root, 'js/src/protocol.gen.ts'), ts)
writeFileSync(join(root, 'ios/Sources/Protocol.gen.swift'), swift)
writeFileSync(join(repo, 'crates/weft-layout/src/protocol.rs'), rust)
console.log(
  'wrote protocol.gen.ts, Protocol.gen.swift, Protocol.gen.kt, weft-layout/src/protocol.rs',
)
